// ── CH6 · MAGIC RESTORED — celebration, blazing aurora ──

svg += `<defs>
  <linearGradient id="lg-ch6" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN?'#04001A':sc.sky1}"/>
