</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-ch6)"/>`;

// ═══ BLAZING NORTHERN LIGHTS (full spectrum, alive!) ═══
const auroraColors = ['#00FF88','#7DF9FF','#DA70D6','#00CED1','#FF69B4','#FFD700','#9370DB','#4ECDC4'];
for (let i = 0; i < 8; i++) {
  const ax = w*(0.05+i*0.12);
  const ay = h*0.06+Math.sin(mt*0.5+i*0.8)*h*0.05;
  const aw = w*0.18;
  const ah = h*0.2+Math.sin(mt*0.4+i*1.1)*h*0.06;
  const aop = 0.06+Math.sin(mt*0.6+i*0.97)*0.04;
  svg += `<ellipse cx="${ax}" cy="${ay}" rx="${aw}" ry="${ah}" fill="${auroraColors[i]}" opacity="${aop}"/>`;
}
// Bright aurora curtains
for (let i = 0; i < 5; i++) {
  const cy2 = h*0.08+i*h*0.03;
  const sway = Math.sin(mt*0.7+i*1.3)*w*0.06;
  const cop = 0.08+Math.sin(mt*0.5+i*0.8)*0.05;
  const cCol = auroraColors[i%auroraColors.length];
  svg += `<path d="M0 ${cy2} Q${w*0.2+sway} ${cy2-12} ${w*0.4} ${cy2+4} T${w*0.7} ${cy2-6} T${w} ${cy2}" fill="none" stroke="${cCol}" stroke-width="${3+Math.sin(mt*0.3+i)*1}" opacity="${cop}"/>`;
}

// Stars (bright, twinkling)
for (let i = 0; i < 40; i++) {
  const sx = (Math.sin(i*127.1+3.7)*0.5+0.5)*w;
  const sy = (Math.sin(i*311.7+1.3)*0.5+0.5)*h*0.3;
  const sr = 0.5+Math.sin(mt*1.5+i*0.9)*0.5;
  svg += `<circle cx="${sx}" cy="${sy}" r="${sr}" fill="#FFF" opacity="${0.5+Math.sin(mt*1.2+i*0.5)*0.4}"/>`;
}

// ── Snow ground (sparkling) ──
svg += `<path d="M0 ${bY-5} Q${w*0.15} ${bY-12} ${w*0.3} ${bY-3} Q${w*0.5} ${bY-10} ${w*0.7} ${bY} Q${w*0.85} ${bY-8} ${w} ${bY-4} L${w} ${h} L0 ${h} Z" fill="${sc.ground}"/>`;
for (let i = 0; i < 20; i++) {
  const spx = w*(0.02+i*0.05);
  const spy = bY+2+Math.sin(i*2.1)*5;
  const spop = 0.3+Math.sin(mt*3+i*1.3)*0.3;
  svg += `<circle cx="${spx}" cy="${spy}" r="1.5" fill="#FFF" opacity="${spop}"/>`;
}

// ── ICE CASTLE (glowing brilliantly!) ──
const cx = w*0.5;
const cy = bY-8;
const castH = 120+w2*8;
// Castle body
svg += `<rect x="${cx-40}" y="${cy-castH*0.5}" width="80" height="${castH*0.5+8}" rx="3" fill="url(#lg-ch6-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
svg += `<path d="M${cx-10} ${cy} L${cx-10} ${cy-18} Q${cx} ${cy-28} ${cx+10} ${cy-18} L${cx+10} ${cy}" fill="rgba(125,249,255,0.45)" stroke="#80B0D0" stroke-width="${ol*0.5}"/>`;
// Left tower
svg += `<rect x="${cx-62}" y="${cy-castH*0.7}" width="25" height="${castH*0.7+8}" rx="2" fill="url(#lg-ch6-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
svg += `<polygon points="${cx-62},${cy-castH*0.7} ${cx-49.5},${cy-castH*0.7-22} ${cx-37},${cy-castH*0.7}" fill="#A0D8F0" stroke="#80B0D0" stroke-width="${ol*0.6}"/>`;
// Right tower
svg += `<rect x="${cx+37}" y="${cy-castH*0.8}" width="25" height="${castH*0.8+8}" rx="2" fill="url(#lg-ch6-castle)" stroke="#80B0D0" stroke-width="${ol}"/>`;
svg += `<polygon points="${cx+37},${cy-castH*0.8} ${cx+49.5},${cy-castH*0.8-26} ${cx+62},${cy-castH*0.8}" fill="#A0D8F0" stroke="#80B0D0" stroke-width="${ol*0.6}"/>`;
// Battlements
for (let i = 0; i < 7; i++) svg += `<rect x="${cx-37+i*10}" y="${cy-castH*0.5-7}" width="5" height="7" rx="1" fill="url(#lg-ch6-castle)" stroke="#80B0D0" stroke-width="${ol*0.3}"/>`;

// BLAZING windows (all lit up!)
const allWin = [[-49,cy-castH*0.55],[-49,cy-castH*0.35],[-22,cy-castH*0.35],[0,cy-castH*0.3],[22,cy-castH*0.35],[49,cy-castH*0.6],[49,cy-castH*0.4],[49,cy-castH*0.2]];
for (let i = 0; i < 8; i++) {
  const wxp = cx+allWin[i][0], wyp = allWin[i][1];
  const pulse = Math.sin(mt*2+i*0.9)*0.5+0.5;
  svg += `<rect x="${wxp-3}" y="${wyp}" width="6" height="9" rx="3" fill="rgba(125,249,255,${0.5+pulse*0.4})" stroke="#80B0D0" stroke-width="${ol*0.3}"/>`;
  svg += `<ellipse cx="${wxp}" cy="${wyp+4}" rx="10" ry="7" fill="rgba(125,249,255,${0.04+pulse*0.04})"/>`;
}

// CRYSTAL ON TOP — blazing!
const crysY = cy-castH*0.8-28;
const crysP = Math.sin(mt*1.5)*0.5+0.5;
svg += `<polygon points="${cx+49.5},${crysY} ${cx+45},${crysY+10} ${cx+54},${crysY+10}" fill="${sc.acc}" opacity="${0.7+crysP*0.3}"/>`;
svg += `<polygon points="${cx+49.5},${crysY} ${cx+47},${crysY+10} ${cx+52},${crysY+10}" fill="#FFF" opacity="${0.3+crysP*0.3}"/>`;
// Crystal beam shooting up
svg += `<polygon points="${cx+49.5},${crysY} ${cx+47},0 ${cx+52},0" fill="${sc.acc}" opacity="${0.03+crysP*0.02}"/>`;
// Radial glow
svg += `<circle cx="${cx+49.5}" cy="${crysY+5}" r="${30+crysP*15}" fill="${sc.acc}" opacity="${0.06+crysP*0.04}"/>`;
// Crystal sparks exploding outward
for (let i = 0; i < 12; i++) {
  const spA = mt*0.8+i*(Math.PI*2/12);
  const spR2 = 15+Math.sin(mt*2+i)*10+i*2;
  const spx = cx+49.5+Math.cos(spA)*spR2;
  const spy = crysY+5+Math.sin(spA)*spR2;
  svg += `<circle cx="${spx}" cy="${spy}" r="${1.5+Math.sin(mt*3+i)*0.5}" fill="${auroraColors[i%auroraColors.length]}" opacity="${0.3+Math.sin(mt*2+i*0.7)*0.3}"/>`;
}

// ═══ MAGIC FIREWORKS ═══
for (let f = 0; f < 4; f++) {
  const fPhase = (mt*0.5+f*1.5)%3;
  if (fPhase < 1.5) {
    const fx = w*(0.15+f*0.22);
    const fy = h*0.2+f*h*0.05;
    const fAge = fPhase;
    const fCol = auroraColors[(f*2)%auroraColors.length];
    for (let s = 0; s < 10; s++) {
      const sa2 = s*(Math.PI*2/10);
      const sr2 = fAge*25;
      const sx2 = fx+Math.cos(sa2)*sr2;
      const sy2 = fy+Math.sin(sa2)*sr2;
      const sop = Math.max(0,0.6-fAge*0.4);
      svg += `<circle cx="${sx2}" cy="${sy2}" r="${2-fAge*0.8}" fill="${fCol}" opacity="${sop}"/>`;
    }
    // Center flash
    if (fAge < 0.3) svg += `<circle cx="${fx}" cy="${fy}" r="${4-fAge*10}" fill="#FFF" opacity="${0.5-fAge}"/>`;
  }
}

// ═══ ALL CHARACTERS CELEBRATING ═══
const partyY = bY+2;

// ── Princess (center, arms raised in triumph) ──
const prx3 = cx, pry3 = partyY-5;
svg += `<polygon points="${prx3},${pry3-28} ${prx3-14},${pry3} ${prx3+14},${pry3}" fill="#6A5ACD" stroke="#483D8B" stroke-width="${ol*0.5}" opacity="0.9"/>`;
svg += `<circle cx="${prx3}" cy="${pry3-33}" r="6" fill="#FFDAB9" stroke="#DEB887" stroke-width="${ol*0.3}"/>`;
const brSw2 = Math.sin(mt*0.9)*3;
svg += `<path d="M${prx3+4} ${pry3-31} Q${prx3+10+brSw2} ${pry3-22} ${prx3+8+brSw2*1.2} ${pry3-12}" fill="none" stroke="#F5DEB3" stroke-width="3" stroke-linecap="round"/>`;
svg += `<path d="M${prx3-5} ${pry3-38} L${prx3-3} ${pry3-42} L${prx3} ${pry3-39} L${prx3+3} ${pry3-42} L${prx3+5} ${pry3-38}" fill="none" stroke="${sc.acc}" stroke-width="1.5"/>`;
const cpFl = Math.sin(mt*1.2)*7;
svg += `<path d="M${prx3+4} ${pry3-24} Q${prx3+16+cpFl} ${pry3-18} ${prx3+12+cpFl*1.5} ${pry3-3}" fill="none" stroke="#9370DB" stroke-width="3" stroke-linecap="round" opacity="0.65"/>`;
// Arms UP celebrating
svg += `<line x1="${prx3-10}" y1="${pry3-20}" x2="${prx3-18}" y2="${pry3-38+Math.sin(mt*3)*4}" stroke="#FFDAB9" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${prx3+10}" y1="${pry3-20}" x2="${prx3+18}" y2="${pry3-38+Math.cos(mt*3)*4}" stroke="#FFDAB9" stroke-width="2" stroke-linecap="round"/>`;
// Magic sparkles from both hands
for (let i = 0; i < 6; i++) {
  for (let side = -1; side <= 1; side += 2) {
    const mgx = prx3+side*18+Math.sin(mt*2.5+i*1.1+side)*8;
    const mgy = pry3-38+Math.cos(mt*2+i*0.8+side)*8;
    svg += `<circle cx="${mgx}" cy="${mgy}" r="${1.5+Math.sin(mt*3+i)*0.5}" fill="${auroraColors[i]}" opacity="${0.4+Math.sin(mt*2+i)*0.3}"/>`;
  }
}

// ── Snowman (dancing!) ──
const smx3 = cx+35, smy3 = partyY;
const smDance = Math.sin(mt*3)*3;
svg += `<circle cx="${smx3+smDance}" cy="${smy3}" r="12" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${smx3+smDance}" cy="${smy3-18}" r="9" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${smx3+smDance}" cy="${smy3-32}" r="7" fill="#F8F8FF" stroke="#C8D8E8" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${smx3+smDance-2}" cy="${smy3-34}" r="1.3" fill="#222"/>`;
svg += `<circle cx="${smx3+smDance+2}" cy="${smy3-34}" r="1.3" fill="#222"/>`;
svg += `<polygon points="${smx3+smDance},${smy3-31} ${smx3+smDance+6},${smy3-30} ${smx3+smDance},${smy3-29}" fill="#FF8C42"/>`;
// Big smile
svg += `<path d="M${smx3+smDance-4} ${smy3-27} Q${smx3+smDance} ${smy3-24} ${smx3+smDance+4} ${smy3-27}" fill="none" stroke="#222" stroke-width="1.2"/>`;
const smArm = Math.sin(mt*4)*15;
svg += `<line x1="${smx3+smDance+9}" y1="${smy3-20}" x2="${smx3+smDance+22}" y2="${smy3-30+smArm}" stroke="#6B4F2A" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${smx3+smDance-9}" y1="${smy3-20}" x2="${smx3+smDance-22}" y2="${smy3-30-smArm}" stroke="#6B4F2A" stroke-width="2" stroke-linecap="round"/>`;

// ── Three pups (jumping/bouncing with joy!) ──
const pupDefs = [
  {x:cx-50, col:'#FF8C42', scol:'#D06B20', phase:0},
  {x:cx-35, col:'#9370DB', scol:'#7B5EA7', phase:1},
  {x:cx-65, col:'#5AAA5A', scol:'#3A8A3A', phase:2}
];
for (let p = 0; p < 3; p++) {
  const ppx = pupDefs[p].x;
  const jumpH = Math.abs(Math.sin(mt*3+pupDefs[p].phase*1.2))*18;
  const ppy = partyY-jumpH;
  svg += `<ellipse cx="${ppx}" cy="${ppy-3}" rx="6.5" ry="4.5" fill="${pupDefs[p].col}" stroke="${pupDefs[p].scol}" stroke-width="${ol*0.4}"/>`;
  svg += `<circle cx="${ppx+4}" cy="${ppy-9}" r="4.5" fill="${pupDefs[p].col}" stroke="${pupDefs[p].scol}" stroke-width="${ol*0.4}"/>`;
  svg += `<polygon points="${ppx+1},${ppy-13} ${ppx},${ppy-18} ${ppx+4},${ppy-14}" fill="${pupDefs[p].scol}"/>`;
  svg += `<polygon points="${ppx+7},${ppy-13} ${ppx+8},${ppy-18} ${ppx+5},${ppy-14}" fill="${pupDefs[p].scol}"/>`;
  // Happy eyes (curved)
  svg += `<path d="M${ppx+2} ${ppy-10} Q${ppx+3.5} ${ppy-12} ${ppx+5} ${ppy-10}" fill="none" stroke="#222" stroke-width="1" stroke-linecap="round"/>`;
  svg += `<path d="M${ppx+5} ${ppy-10} Q${ppx+6.5} ${ppy-12} ${ppx+8} ${ppy-10}" fill="none" stroke="#222" stroke-width="1" stroke-linecap="round"/>`;
  // Legs spread in air
  const legS = jumpH > 8 ? 3 : 0;
  svg += `<line x1="${ppx-4}" y1="${ppy+1}" x2="${ppx-6-legS}" y2="${ppy+7}" stroke="${pupDefs[p].scol}" stroke-width="2" stroke-linecap="round"/>`;
  svg += `<line x1="${ppx+4}" y1="${ppy+1}" x2="${ppx+6+legS}" y2="${ppy+7}" stroke="${pupDefs[p].scol}" stroke-width="2" stroke-linecap="round"/>`;
  // Tail wagging fast!
  const ptail2 = Math.sin(mt*6+p*1.5)*12;
  svg += `<path d="M${ppx-7} ${ppy-4} Q${ppx-12} ${ppy-12+ptail2} ${ppx-10} ${ppy-16+ptail2*0.5}" fill="none" stroke="${pupDefs[p].col}" stroke-width="2.5" stroke-linecap="round"/>`;
}

// ── Deer family (right, happy) ──
const ddx4 = cx+70, ddy4 = partyY-5;
svg += `<ellipse cx="${ddx4}" cy="${ddy4}" rx="14" ry="9" fill="#C4862D" stroke="#A06820" stroke-width="${ol*0.4}"/>`;
svg += `<path d="M${ddx4+8} ${ddy4-5} Q${ddx4+12} ${ddy4-15} ${ddx4+10} ${ddy4-22}" fill="none" stroke="#C4862D" stroke-width="6" stroke-linecap="round"/>`;
svg += `<circle cx="${ddx4+10}" cy="${ddy4-25}" r="5" fill="#D4964A"/>`;
svg += `<path d="M${ddx4+7} ${ddy4-29} Q${ddx4+3} ${ddy4-38} ${ddx4+2} ${ddy4-42}" fill="none" stroke="#8B6B4A" stroke-width="1.3" stroke-linecap="round"/>`;
svg += `<path d="M${ddx4+13} ${ddy4-29} Q${ddx4+17} ${ddy4-38} ${ddx4+18} ${ddy4-42}" fill="none" stroke="#8B6B4A" stroke-width="1.3" stroke-linecap="round"/>`;
svg += `<circle cx="${ddx4+12}" cy="${ddy4-26}" r="1" fill="#222"/>`;
// Fawn nuzzling parent
const fwx2 = ddx4-12, fwy2 = ddy4+3;
svg += `<ellipse cx="${fwx2}" cy="${fwy2}" rx="8" ry="5" fill="#D4A050"/>`;
svg += `<circle cx="${fwx2+5}" cy="${fwy2-7}" r="3.5" fill="#D4A050"/>`;
svg += `<circle cx="${fwx2+7}" cy="${fwy2-8}" r="0.8" fill="#222"/>`;

// ── Owl (perched, content) ──
const olx2 = cx-80, oly2 = partyY-20;
svg += `<ellipse cx="${olx2}" cy="${oly2+2}" rx="7" ry="8" fill="#8B6B4A"/>`;
svg += `<circle cx="${olx2}" cy="${oly2-7}" r="6" fill="#9B7B5A"/>`;
svg += `<polygon points="${olx2-4},${oly2-11} ${olx2-2},${oly2-17} ${olx2},${oly2-11}" fill="#7B5B3A"/>`;
svg += `<polygon points="${olx2},${oly2-11} ${olx2+2},${oly2-17} ${olx2+4},${oly2-11}" fill="#7B5B3A"/>`;
// Happy owl eyes
svg += `<path d="M${olx2-5} ${oly2-8} Q${olx2-3} ${oly2-10} ${olx2-1} ${oly2-8}" fill="none" stroke="#FFD700" stroke-width="1.5" stroke-linecap="round"/>`;
svg += `<path d="M${olx2+1} ${oly2-8} Q${olx2+3} ${oly2-10} ${olx2+5} ${oly2-8}" fill="none" stroke="#FFD700" stroke-width="1.5" stroke-linecap="round"/>`;
svg += `<polygon points="${olx2},${oly2-6} ${olx2-1.5},${oly2-4} ${olx2+1.5},${oly2-4}" fill="#DAA520"/>`;

// ═══ GOLDEN BUTTERFLY (final flourish — spiraling upward) ═══
const bfSpiral = mt*1.5;
const bfx6 = cx+Math.cos(bfSpiral)*30;
const bfy6 = partyY-50-((mt*5)%80);
const bfW6 = Math.sin(mt*7)*5;
svg += `<ellipse cx="${bfx6-3}" cy="${bfy6}" rx="${4+bfW6*0.3}" ry="5" fill="#FFD700" opacity="0.9" transform="rotate(${-bfW6*2} ${bfx6-3} ${bfy6})"/>`;
svg += `<ellipse cx="${bfx6+3}" cy="${bfy6}" rx="${4+bfW6*0.3}" ry="5" fill="#FFD700" opacity="0.9" transform="rotate(${bfW6*2} ${bfx6+3} ${bfy6})"/>`;
svg += `<ellipse cx="${bfx6}" cy="${bfy6}" rx="1" ry="3.5" fill="#8B6914"/>`;
// Long golden trail
for (let i = 0; i < 12; i++) {
  const trx = cx+Math.cos(bfSpiral-i*0.15)*30;
  const tri6 = bfy6+i*5;
  svg += `<circle cx="${trx}" cy="${tri6}" r="${2-i*0.12}" fill="#FFD700" opacity="${0.3-i*0.02}"/>`;
}
svg += `<circle cx="${bfx6}" cy="${bfy6}" r="${12+w3*6}" fill="#FFD700" opacity="${0.05+w1*0.04}"/>`;

// ── Gentle snowflakes (peaceful now) ──
for (let i = 0; i < 15; i++) {
  const sfx = (Math.sin(i*73.1+5.3)*0.5+0.5)*w+Math.sin(mt*0.6+i*0.4)*10;
  const sfy = ((mt*5+i*(h/15))%(h+20))-10;
  svg += `<circle cx="${sfx%w}" cy="${sfy}" r="${1+Math.sin(i*2.3)*0.5}" fill="#FFF" opacity="${0.3+Math.sin(mt*1.5+i*0.7)*0.2}"/>`;
}

// Moon (crescent, peaceful)
svg += `<circle cx="${w*0.88}" cy="${h*0.08}" r="16" fill="#EDE8DF" opacity="0.85"/>`;
svg += `<circle cx="${w*0.88+5}" cy="${h*0.08-4}" r="13" fill="#04001A" opacity="0.9"/>`;
svg += `<ellipse cx="${w*0.88}" cy="${h*0.08}" rx="50" ry="35" fill="rgba(237,232,223,0.02)"/>`;
